// Billing page visual baselines (#256): every viewport x theme project (360/768/1280, light and
// dark) with the clock frozen: the paid page with invoices, payment failed in grace, the Junior
// plan and empty invoices. The grace dates and countdown are computed on the server from the real
// clock, so they are masked. Baselines live in e2e/__screenshots__ and are only ever generated by
// the e2e workflow's `update_snapshots` dispatch in the pinned Playwright image (see
// e2e/README.md); without one the test is skipped.
import { existsSync } from 'node:fs';

import type { Page, TestInfo } from '@playwright/test';

import type { AsUser } from '../../fixtures/auth.ts';
import type { WorkerDb } from '../../fixtures/db.ts';
import { expect, test } from '../../fixtures/index.ts';
import { shellReady } from '../shell/helpers.ts';

import { downgradeToJunior, seedBilling, setGrace } from './billing-data.ts';

function skipWithoutBaseline(testInfo: TestInfo, name: string) {
  const baseline = testInfo.snapshotPath(name, { kind: 'screenshot' });
  test.skip(
    testInfo.config.updateSnapshots === 'none' && !existsSync(baseline),
    'no baseline yet: dispatch the e2e workflow with update_snapshots',
  );
}

async function snap(page: Page, name: string) {
  await expect(page).toHaveScreenshot(name, {
    animations: 'disabled',
    caret: 'hide',
    fullPage: true,
    mask: [
      page.locator('[data-banner="grace"] [data-slot="alert-description"]'),
      page.locator('[data-status="grace"]'),
    ],
  });
}

async function openBilling(page: Page, asUser: AsUser) {
  await asUser('owner', { path: 'billing' });
  await expect(page.getByRole('heading', { level: 1, name: 'Billing' })).toBeVisible();
  await shellReady(page);
}

interface Shot {
  name: string;
  /** Prepares the worker database before the page opens. */
  data: (db: WorkerDb) => Promise<void>;
}

const SHOTS: readonly Shot[] = [
  { name: 'billing-paid.png', data: (db) => seedBilling(db.name, 'chennai-solo') },
  {
    name: 'billing-grace.png',
    data: async (db) => {
      await seedBilling(db.name, 'chennai-solo');
      await setGrace(db.name, 'chennai-solo', 3);
    },
  },
  { name: 'billing-junior.png', data: (db) => downgradeToJunior(db.name, 'chennai-solo') },
  { name: 'billing-empty.png', data: () => Promise.resolve() },
];

test.describe('billing visual baselines', () => {
  for (const shot of SHOTS) {
    test(
      shot.name.replace(/\.png$/, ''),
      { tag: '@visual' },
      async ({ page, asUser, db }, testInfo) => {
        skipWithoutBaseline(testInfo, shot.name);
        await shot.data(db);
        await openBilling(page, asUser);
        await snap(page, shot.name);
      },
    );
  }
});
